/**
 * Wild edible plant ("green edible") catalog — Tahoe–Truckee / Sierra Nevada seed set.
 *
 * Researched against reputable sources (Calflora/Calscape, USDA PLANTS & Forest
 * Service FEIS, Lady Bird Johnson Wildflower Center, university extension, and
 * poison-control / toxicology references for the warning entries) and scoped to
 * montane Sierra phenology. Every entry is marked `autoCompiled` so the detail
 * page shows the "verify before foraging" caveat — treat as a field aid, not a
 * substitute for expert identification.
 *
 * The five `deadly` / `toxic` entries at the end are NOT foods. They are
 * catalogued as warning cards so an edible's lookalike can deep-link to a real
 * hazard page (e.g. wild onion → death camas), mirroring how the mushroom
 * catalog also catalogues toxic species.
 */
import type { PlantSpecies } from "../../plant-types";
import type { Verification } from "../../species-types";

